33	/* * * * * * * * * * * * * * * * * * * * * * * 
34	Memory Layout
35	0x5000_0000 ~ 0x5020_0000       BBL
36	0x5020_0000 ~ 0x5040_0000       Boot
37	0x5040_0000 ~ 0x5140_0000       Kernel
38	0x5140_0000 ~ 0x5140_2000       Kernel Stack
39	0x5140_2000 ~ 0x5200_0000       Kernel Mem
40	0x5200_0000 ~ 0x5e00_0000       User Mem
41	0x5e00_0000 ~ 0x5f00_0000       Page Table
42	0x5f00_0000 ~ 0x6000_0000       FS Cache
43	* * * * * * * * * * * * * * * * * * * * * * */
44	
45	#define PAGE_SIZE 4096
46	#define INIT_KERNEL_STACK   0xffffffc051400000lu    //kva
47	#define USER_STACK_ADDR     0xf00010000lu           //va
48	
49	#define KERNEL_MEM_BEGIN    0x51402000lu            //pa
50	#define KERNEL_MEM_END      0x52000000lu            //pa
51	#define USER_MEM_BEGIN      0x52000000lu            //pa
52	#define USER_MEM_END        0x5e000000lu            //pa
53	#define PGDIR_END           0x5f000000lu            //pa
54	#define MEM_END             0x60000000lu            //pa
55	
56	#define SWAP_BEGIN 2048
57	
58	/* Rounding: only works for n = power of two */
59	#define ROUND(a, n)     (((((uint64_t)(a))+(n)-1)) & ~((n)-1))
60	#define ROUNDDOWN(a, n) (((uint64_t)(a)) & ~((n)-1))
61	
62	extern ptr_t kernel_memCurr;
63	extern ptr_t user_memCurr;
64	
65	#define FREE_PGDIR_ADDR (PGDIR_PA + 3 * PAGE_SIZE)
66	#define PGDIR_PAGE_NUM ((PGDIR_END - FREE_PGDIR_ADDR) / PAGE_SIZE)
67	typedef struct pgdir_page{
68	    uint8_t valid;
69	}pgdir_page_t;
70	extern pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];
71	
72	#define USER_MEM_SIZE (USER_MEM_END - USER_MEM_BEGIN)
73	#define USER_PAGE_NUM (USER_MEM_SIZE / PAGE_SIZE)
