604	/****************************************************************************/
605	/**
606	 *
607	 * This function demonstrates the usage of the EMACPS by sending
608	 *and receiving a single frame in DMA interrupt mode. The source
609	 *packet will be described by two descriptors. It will be received
610	 *into a buffer described by a single descriptor.
611	 *
612	 * @param	EmacPsInstancePtr is a pointer to the instance of the
613	 *EmacPs driver.
614	 *
615	 * @return	XST_SUCCESS to indicate success, otherwise XST_FAILURE.
616	 *
617	 * @note		None.
618	 *
619	 *****************************************************************************/
620	LONG EmacPsDmaSingleFrameIntrExample(XEmacPs *EmacPsInstancePtr)
621	{
622	    u32 PayloadSize = 1000;
623	
624	    /*
625	     * Clear variables shared with callbacks
626	     */
627	    FramesRx     = 0;
628	    FramesTx     = 0;
629	    DeviceErrors = 0;
630	
631	    /*
632	     * Calculate the frame length (not including FCS)
633	     */
634	    TxFrameLength = XEMACPS_HDR_SIZE + PayloadSize;
635	
636	    /*
637	     * Setup packet to be transmitted
638	     */
639	    EmacPsUtilFrameHdrFormatMAC(&TxFrame, BroadcastMAC);
640	    EmacPsUtilFrameHdrFormatType(&TxFrame, PayloadSize);
641	    EmacPsUtilFrameSetPayloadData(&TxFrame, PayloadSize);
642		xil_printf("Setup packet to be transmitted\n\r");
643	    Xil_DCacheFlushRange((UINTPTR)&TxFrame, sizeof(EthernetFrame));
644	
645	    /*
646	     * Clear out receive packet memory area
647	     */
648	    EmacPsUtilFrameMemClear(&RxFrame);
649		xil_printf("Clear out receive packet memory area\n\r");
650	    Xil_DCacheFlushRange((UINTPTR)&RxFrame, sizeof(EthernetFrame));
651	
652	    EmacPsRecv(EmacPsInstancePtr, &RxFrame, 1);
653	    EmacPsSend(EmacPsInstancePtr, &TxFrame, TxFrameLength);
654	
655	    EmacPsWaitSend(EmacPsInstancePtr);
656	    u32 RxFrLen;
657	    EmacPsWaitRecv(EmacPsInstancePtr, 1, &RxFrLen);
658	
659	    /*
660	     * Start the device
661	     */
662	
663	    // XEmacPs_Start(EmacPsInstancePtr);
664		// xil_printf("Start device\n\r");
665	
666	    /* Start transmit */
667	    // XEmacPs_Transmit(EmacPsInstancePtr);
668		// xil_printf("Start transmit\n\r"); 
669	
670	
671	    if (EmacPsUtilFrameVerify(&TxFrame, &RxFrame) != 0) {
672	        for (int i = 0; i < (TxFrameLength / 16) - 1; ++i) {
673	            xil_printf("Tx > ");
674	            for (int j = 0; j < 16; ++j) {
675	                xil_printf("%02x ", ((u8*)&TxFrame)[i*16 + j]);
676	            }
677	            xil_printf("\n\rRx > ");
678	            for (int j = 0; j < 16; ++j) {
679	                xil_printf("%02x ", ((u8*)&RxFrame)[i*16 + j]);
680	            }
681	            xil_printf("\n\r");
682	        }
683	        EmacPsUtilErrorTrap("Data mismatch");
684	        return XST_FAILURE;
685	    } else {
686			xil_printf("Data match success\n\r");
687		}
688	
689	    /*
690	     * Finished this example. If everything worked correctly, all
691	     * TxBDs and RxBDs should be free for allocation. Stop the
692	     * device.
693	     */
694	    XEmacPs_Stop(EmacPsInstancePtr);
695	
696	    return XST_SUCCESS;
697	}
