123	static void write_segment(Elf64_Phdr phdr, FILE * fp,
124	                          FILE * img, int *nbytes)
125	{
126		/* only write loadable segments with non-zero memory size */
127		if (phdr.p_type != PT_LOAD || phdr.p_memsz == 0) {
128			return;
129		}
130	
131		/* 512 bytes align */
132		int bytes;
133		if(phdr.p_memsz % 512 == 0) {
134			bytes = phdr.p_memsz;
135		}
136		else {
137			bytes = phdr.p_memsz + (512 - phdr.p_memsz % 512);
138		}
139	
140		/* copy the segment in fixed-size (one sector) chunks,
141		 * zero-padding the final partial sector */
142		char segment_file[512];
143		int remaining = phdr.p_memsz;
144		int filesz = phdr.p_filesz;
145	
146		fseek(fp, phdr.p_offset, SEEK_SET);
147		while (remaining > 0) {
148			int chunk = remaining > 512 ? 512 : remaining;
149			int from_file = filesz > chunk ? chunk : filesz;
150	
151			memset(segment_file, 0, sizeof(segment_file));
152			if (from_file > 0) {
153				fread(segment_file, from_file, 1, fp);
154			}
155			fwrite(segment_file, chunk, 1, img);
156	
157			remaining -= chunk;
158			filesz -= from_file;
159		}
160	
161		(*nbytes) += bytes;
162	
163		return;
164	}
