166	static void write_os_size(int nbytes, FILE * img)
167	{
168		long OS_SIZE_LOC = 508;
169		nbytes = nbytes / 512 - 1;
170		fseek(img, OS_SIZE_LOC, SEEK_SET);
171		fwrite(&nbytes, 2, 1, img);
172		printf("os_size: %d sectors\n", nbytes);

