52	    pt_regs->regs[1] = (reg_t)entry_point;      //ra
53	    pt_regs->regs[2] = (reg_t)user_stack;       //sp
54	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
55	    pt_regs->sstatus = (reg_t)SR_SPIE;          //SPP = 0, SPIE = 1
56	    pt_regs->sepc = (reg_t)entry_point;         //sepc
