23	} echo_shm_vars_t;
24	
25	void shm_read(char* shmbuf, atomic_long *_available, char* buf, size_t size)
26	{
27	    while (size > 0) {
28	        while(atomic_load_d(_available) != 1);
29	
30	        int sz = size > FIFO_BUF_MAX ? FIFO_BUF_MAX : size;
31	        memcpy(buf, shmbuf, sz);
32	        size -= sz;
33	
34	        atomic_exchange_d(_available, 0);
35	    }
36	}
37	
38	void shm_write(char* shmbuf, atomic_long *_available, char* buf, size_t size)
39	{
40	    while (size > 0) {
41	        while(atomic_load_d(_available) != 0);
42	
43	        int sz = size > FIFO_BUF_MAX ? FIFO_BUF_MAX : size;
44	        memcpy(shmbuf, buf, sz);
45	        size -= sz;
46	
47	        atomic_exchange_d(_available, 1);
48	    }
49	}
50	
51	int is_first(echo_shm_vars_t *vars)
52	{
53	    unsigned long my = atomic_exchange_d(&vars->magic_number, MAGIC);
54	    return my != MAGIC;
55	}
