7	// replace all illegal character with `_`
8	char *file_name_to_variable_name(char *name)
9	{
10	    int l = strlen(name);
11	    for (int i = 0; i < l; ++i) {
12	        if (!isalpha(name[i]) && !isdigit(name[i])) {
13	            name[i] = '_';
14	        }
15	    }
16	    return name;
17	}
