16	void extend(Records* self)
17	{
18	    if (self->capicity == 0) {
19	        self->capicity = RECORDS_INIT_SIZE;
20	    } else {
21	        self->capicity *= 2;
22	    }
23	    self->record = (char***)realloc(
24	        self->record, sizeof(char**) * self->capicity);
25	    self->record[0] = (char**)realloc(
26	        self->record[0], sizeof(char*) * 3 * self->capicity);
27	    for (int i = 0; i < self->capicity; ++i) {
28	        self->record[i] = self->record[0] + i * 3;
29	    }
30	    assert(self->record != NULL);
31	}
