112	void append_record(Records* self, char* varname)
113	{
114	    while (self->size >= self->capicity) {
115	        extend(self);
116	    }
117	
118	    char* length_var_name = (char*) malloc(sizeof(char) * (strlen(varname) + sizeof("_length")));
119	    strcpy(length_var_name, "_length");
120	    strcat(length_var_name, &varname[sizeof("_elf") - 1]);
121	    self->record[self->size][0] = simplify(self, varname);
122	    self->record[self->size][1] = varname;
123	    self->record[self->size][2] = length_var_name;
124	    ++self->size;
125	}
