139	char* variable_name(const char* buffer)
140	{
141	    // skip `extern unsigned char `
142	    char* ret       = NULL;
143	    const char* var = buffer + sizeof(char) * strlen("extern unsigned char ");
144	    int l           = strlen(var);
145	    ret             = (char*)malloc(
