152	FILE* open_file_with_suffix(
153	    const char* file_name, const char* suffix)
154	{
155	    char* file_name_buf = (char*)malloc(
156	        sizeof(char) * (strlen(file_name) + strlen(suffix) + 1));
157	    strcpy(file_name_buf, file_name);
158	    strcat(file_name_buf, suffix);
159	    FILE* ret = fopen(file_name_buf, "r+");
160	    free(file_name_buf);
161	    return ret;
162	}
