164	int main(int argc, char* argv[])
165	{
166	    if (argc != 2) {
167	        printf("Usage: generateMapping <user_programs>\n");
168	        return -1;
169	    }
170	
171	    FILE* header = open_file_with_suffix(argv[1], ".h");
172	    if (header == NULL) {
173	        printf("Can not open %s.h!\n", argv[1]);
174	        return -1;
175	    }
176	
177	    Records records = {NULL, 0, 0};
178	    char buffer[MAX_LINE_BUFF];
179	    while (fgets(buffer, MAX_LINE_BUFF, header) != 0) {
180	        if (start_with(buffer, "extern unsigned char")) {
181	            buffer[strlen(buffer) - 4] = '\0';
182	            append_record(&records, variable_name(buffer));
183	        }
184	    }
185	
186	    FILE* source = open_file_with_suffix(argv[1], ".c");
187	    if (source == NULL) {
188	        printf("Can not open %s.h!\n", argv[1]);
189	        return -1;
190	    }
191	    write_to_file(&records, header, source);
192	
193	    fclose(header);
194	    fclose(source);
195	
196	    return 0;
197	}

