526	int do_link(char* filename, char* newfile, int mode)
527	{
528	    /* Search Parent Dir */
529	    enable_sum();
530	
531	    int filename_pos = 0;
532	    dir_t* cur_dir;
533	    uint16_t lastdir_inode;
534	    uint32_t lastdir_block;
535	
536	    // search from root dir / current dir?
537	    if(filename[filename_pos] == '/'){
538	        read_superblock();
539	        read_block(superblock->root_block_id);
540	        cur_dir = cached_block_base;
541	        lastdir_inode = superblock->root_inode_id;
542	        lastdir_block = superblock->root_block_id;
543	        filename_pos++;    
544	    }
545	    else{
546	        read_block(current_dir_block);
547	        cur_dir = cached_block_base;
548	        lastdir_inode = current_dir_inode;
549	        lastdir_block = current_dir_block;
550	    }
551	
552	    char nextdirname[29];
553	    while(1){
554	        // Get name of next dir
555	        int nextdirname_pos = 0;
556	        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
557	            nextdirname[nextdirname_pos++] = filename[filename_pos++];
558	        }
559	        nextdirname[nextdirname_pos] = '\0';
560	
561	        // Last?
562	        if(filename[filename_pos] == '\0'){
563	            break;
564	        }
565	
566	        // Search
567	        int i = 0;
568	        uint16_t nextdir_inode_id;
569	        uint32_t nextdir_block_id;
570	        for(i = 0; i < 128; i++){
571	            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
572	                nextdir_inode_id = cur_dir->entry[i].inode;
573	                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
574	                nextdir_block_id = nextdir_inode->direct_blocks[0];
575	                lastdir_inode = nextdir_inode_id;
576	                lastdir_block = nextdir_block_id;
577	                break;
578	            }
579	        }
580	        if(i == 128){
581	            disable_sum();
582	            return 0;
583	        }
584	
585	        filename_pos++;
586	        read_block(nextdir_block_id);
587	        cur_dir = cached_block_base;
588	    }
589	
590	    disable_sum();
591	    /* Search Parent Dir End */
592	
593	    uint16_t inode_id;
594	    int type;
595	
596	    read_block(lastdir_block);
597	    cur_dir = cached_block_base;
598	    for(int i = 0; i < 128; i++){
599	        if(cur_dir->entry[i].type != EMPTY && !strcmp(cur_dir->entry[i].name, nextdirname)){
600	            inode_id = cur_dir->entry[i].inode;
601	            type = cur_dir->entry[i].type;
602	            break;
603	        }
604	    }
605	
606	    enable_sum();
607	    if(mode == 0){
608	        if(type == DIR){
609	            disable_sum();
610	            return 0;
611	        }
612	
613	        inode_t* inode = read_inode(inode_id);
614	        inode->link = inode->link + 1;
615	        write_inode(inode_id);
616	
617	        read_block(current_dir_block);
618	        cur_dir = cached_block_base;
619	        for(int i = 0; i < 128; i++){
620	            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
621	                disable_sum();
622	                return 0;
623	            }
624	        }
625	        for(int i = 0; i < 128; i++){
626	            if(cur_dir->entry[i].type == EMPTY){
627	                cur_dir->entry[i].type = FILE;
628	                strcpy(cur_dir->entry[i].name, newfile);
629	                cur_dir->entry[i].inode = inode_id;
630	                write_block(current_dir_block);
631	                disable_sum();
632	                return 1;
633	            }
634	        }
635	    }
636	    else if(mode == 1){
637	        read_block(current_dir_block);
638	        cur_dir = cached_block_base;
639	        for(int i = 0; i < 128; i++){
640	            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
641	                disable_sum();
642	                return 0;
643	            }
644	        }
645	        for(int i = 0; i < 128; i++){
646	            if(cur_dir->entry[i].type == EMPTY){
647	                uint16_t new_inode_id = alloc_inode();
648	                cur_dir->entry[i].type = type;
649	                strcpy(cur_dir->entry[i].name, newfile);
650	                cur_dir->entry[i].inode = new_inode_id;
651	                write_block(current_dir_block);
652	                
653	                inode_t* inode = read_inode(inode_id);
654	                uint32_t direct[10];
655	                uint32_t indirect[2];
656	                uint64_t size;
657	                uint32_t link;
658	                for(int j = 0; j < 10; j++){
659	                    direct[i] = inode->direct_blocks[i];
660	                }
661	                indirect[0] = inode->indirect_blocks[0];
662	                indirect[1] = inode->indirect_blocks[1];
663	                size = inode->size;
664	                link = inode->link;
665	
666	                inode = read_inode(new_inode_id);
667	                inode->mode = 1;
668	                inode->owner = current_running[cpu_id]->pid;
669	                inode->size = size;
670	                inode->link = link;
671	                for(int j = 0; j < 10; j++){
672	                    inode->direct_blocks[i] = direct[i];
673	                }
674	                inode->indirect_blocks[0] = indirect[0];
675	                inode->indirect_blocks[1] = indirect[1];
676	                write_inode(new_inode_id);
677	
678	                return 1;
679	            }
680	        }
681	    }
682	}

