202	int do_fopen(char* filename, int access)
203	{
204	    /* Search Parent Dir */
205	    enable_sum();  
206	
207	    int filename_pos = 0;
208	    dir_t* cur_dir;
209	    uint16_t lastdir_inode;
210	    uint32_t lastdir_block;
211	
212	    // search from root dir / current dir?
213	    if(filename[filename_pos] == '/'){
214	        read_superblock();
215	        read_block(superblock->root_block_id);
216	        cur_dir = cached_block_base;
217	        lastdir_inode = superblock->root_inode_id;
218	        lastdir_block = superblock->root_block_id;
219	        filename_pos++;    
220	    }
221	    else{
222	        read_block(current_dir_block);
223	        cur_dir = cached_block_base;
224	        lastdir_inode = current_dir_inode;
225	        lastdir_block = current_dir_block;
226	    }
227	
228	    char nextdirname[29];
229	    while(1){
230	        // Get name of next dir
231	        int nextdirname_pos = 0;
232	        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
233	            nextdirname[nextdirname_pos++] = filename[filename_pos++];
234	        }
235	        nextdirname[nextdirname_pos] = '\0';
236	
237	        // Last?
238	        if(filename[filename_pos] == '\0'){
239	            break;
240	        }
241	
242	        // Search
243	        int i = 0;
244	        uint16_t nextdir_inode_id;
245	        uint32_t nextdir_block_id;
246	        for(i = 0; i < 128; i++){
247	            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
248	                nextdir_inode_id = cur_dir->entry[i].inode;
249	                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
250	                nextdir_block_id = nextdir_inode->direct_blocks[0];
251	                lastdir_inode = nextdir_inode_id;
252	                lastdir_block = nextdir_block_id;
253	                break;
254	            }
255	        }
256	        if(i == 128){
257	            disable_sum();
258	            return 0;
259	        }
260	
261	        filename_pos++;
262	        read_block(nextdir_block_id);
263	        cur_dir = cached_block_base;
264	    }
265	
266	    disable_sum();
267	    /* Search Parent Dir End */
268	
269	    /* Modify FD */
270	    read_block(lastdir_block);
271	    cur_dir = cached_block_base;
272	    int fd_id;
273	    for(fd_id = 0; fd_id < 10; fd_id++){
274	        if(fd_list[fd_id].access == O_EMPTY){
275	            break;
276	        }
277	    }
278	    
279	    for(int i = 0; i < 128; i++){
280	        if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, nextdirname)){
281	            fd_list[fd_id].access = access;
282	            fd_list[fd_id].inode = cur_dir->entry[i].inode;
283	            fd_list[fd_id].rd_pos = 0;
284	            fd_list[fd_id].wr_pos = 0;
285	            break;
286	        }
287	    }
288	
289	    return fd_id;
290	}
291	
292	int do_fread(int fd, char* buffer, int size)
293	{
294	    if(fd_list[fd].access == O_WRONLY){
295	        return 0;
296	    }
297	
298	    inode_t* inode = read_inode(fd_list[fd].inode);
299	    if(fd_list[fd].rd_pos + size > inode->size){
300	        return 0;
301	    }
302	     
303	    int copied_byte = 0;
304	    while(copied_byte < size){
305	        int block_num = fd_list[fd].rd_pos / 4096;
306	        int block_id;
307	        if(block_num < 10){
308	            block_id = inode->direct_blocks[block_num];
309	        }
310	        else if(block_num >= 10 && block_num < 10 + 1024){
311	            block_id = inode->indirect_blocks[0];
312	            read_block(block_id);
313	            uint32_t* pointer = cached_block_base;
314	            block_id = *(pointer + block_num - 10);
315	        }
316	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
317	            block_id = inode->indirect_blocks[1];
318	            read_block(block_id);
319	            uint32_t* pointer = cached_block_base;
320	            block_id = *(pointer + block_num - 10 - 1024);
321	        }
322	        read_block(block_id);
323	
324	        int offset = fd_list[fd].rd_pos % 4096;
325	        int copy_byte;
326	        if(size - copied_byte <= 4096 - offset){
327	            copy_byte = size - copied_byte;
328	        }
329	        else{
330	            copy_byte = 4096 - offset;
331	        }
332	
333	        enable_sum();
334	        memcpy(buffer + copied_byte, ((uint8_t*)cached_block_base) + offset, copy_byte);
335	        disable_sum();
336	
337	        copied_byte += copy_byte;
338	        fd_list[fd].rd_pos += copy_byte;
339	    }
340	
341	    return size;
342	}
343	
344	int do_fwrite(int fd, char* buffer, int size)
345	{
346	    if(fd_list[fd].access == O_RDONLY){
347	        return 0;
348	    }
349	
350	    inode_t* inode = read_inode(fd_list[fd].inode);
351	
352	    int cur_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
353	    inode->size = inode->size + size;
354	    int total_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
355	    int needed_block = total_block - cur_block;
356	
357	    if(total_block >= 10 && cur_block < 10){
358	        inode->indirect_blocks[0] = alloc_block();
359	    }
360	    if(total_block >= 10 + 1024 && cur_block < 10 + 1024){
361	        inode->indirect_blocks[1] = alloc_block();
362	    }
363	
364	    for(int i = 0; i < needed_block; i++){
365	        int block_num = cur_block + i;
366	        if(block_num < 10){
367	            inode->direct_blocks[block_num] = alloc_block();
368	        }
369	        else if(block_num >= 10 && block_num < 10 + 1024){
370	            int block_id = inode->indirect_blocks[0];
371	            read_block(block_id);
372	            uint32_t* pointer = cached_block_base;
373	            *(pointer + block_num - 10) = alloc_block();
374	            write_block(block_id);
375	        }
376	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
377	            int block_id = inode->indirect_blocks[1];
378	            read_block(block_id);
379	            uint32_t* pointer = cached_block_base;
380	            *(pointer + block_num - 10 - 1024) = alloc_block();
381	            write_block(block_id);
382	        }
383	    }
384	    
385	    write_inode(fd_list[fd].inode);
386	
387	    int copied_byte = 0;
388	    while(copied_byte < size){
389	        int block_num = fd_list[fd].wr_pos / 4096;
390	        int block_id; 
391	        if(block_num < 10){
392	            block_id = inode->direct_blocks[block_num];
393	        }
394	        else if(block_num >= 10 && block_num < 10 + 1024){
395	            block_id = inode->indirect_blocks[0];
396	            read_block(block_id);
397	            uint32_t *pointer = cached_block_base;
398	            block_id = *(pointer + block_num - 10);
399	        }
400	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
401	            block_id = inode->indirect_blocks[1];
402	            read_block(block_id);
403	            uint32_t *pointer = cached_block_base;
404	            block_id = *(pointer + block_num - 10 - 1024);
405	        }
406	
407	        read_block(block_id);
408	
409	        int offset = fd_list[fd].wr_pos % 4096;
410	        int copy_byte;
411	        if(size - copied_byte <= 4096 - offset){
412	            copy_byte = size - copied_byte;
413	        }
414	        else{
415	            copy_byte = 4096 - offset;
416	        }
417	
418	        enable_sum();
419	        memcpy(((uint8_t*)cached_block_base) + offset, buffer + copied_byte, copy_byte);
420	        write_block(block_id);
421	        disable_sum();
422	
423	        copied_byte += copy_byte;
424	        fd_list[fd].wr_pos += copy_byte;
425	    }
426	
427	    return size;
428	}
