33	int mthread_cond_init(mthread_cond_t *cond)
34	{
35	    atomic_exchange(cond, 0);
36	    return 1;
37	}
38	int mthread_cond_destroy(mthread_cond_t *cond) 
39	{
40	    sys_futex_wakeup((unsigned long*)cond, *cond);
41	    atomic_exchange(cond, -1);
42	    return 1;
43	}
44	int mthread_cond_wait(mthread_cond_t *cond, int binsem_id)
45	{
46	    fetch_add(cond, 1);
47	    sys_binsem_op(binsem_id, BINSEM_OP_UNLOCK);
48	    sys_futex_wait((unsigned long*)cond);
49	    sys_binsem_op(binsem_id, BINSEM_OP_LOCK);
50	    return 1;
51	}
52	int mthread_cond_signal(mthread_cond_t *cond)
53	{
54	    sys_futex_wakeup((unsigned long*)cond, 1);
55	    fetch_sub(cond, 1);
56	    return 1;
57	}
58	int mthread_cond_broadcast(mthread_cond_t *cond)
59	{
60	    sys_futex_wakeup((unsigned long*)cond, *cond);
61	    atomic_exchange(cond, 0);
62	    return 1;
63	}
