args.new_string:
list_node_t* max_priority_node(void)
{
    uint64_t current_tick = get_ticks();

    /*
     * The effective priority of a ready task is its static priority aged
     * by the number of timer intervals it has waited in the ready queue;
     * the lower the value, the higher the priority.
     */
    list_node_t *max_node = ready_queue.next;
    pcb_t *max_pcb = list_entry(max_node, pcb_t, list);
    int max_priority = (int)max_pcb->priority
        - (int)((current_tick - max_pcb->ready_tick) / timer_interval);

    list_node_t *node;
    for (node = ready_queue.next->next; node != &ready_queue; node = node->next) {
        pcb_t *pcb = list_entry(node, pcb_t, list);
        int priority = (int)pcb->priority
            - (int)((current_tick - pcb->ready_tick) / timer_interval);
        if (priority < max_priority) {
            max_node = node;
            max_priority = priority;
        }
    }

    return max_node;
}

