void timer_check()
{
    disable_preempt();

    uint64_t current_tick = get_ticks();
    list_node_t *node = timer_queue.next;
    while (node != &timer_queue) {
        timer_t *timer = list_entry(node, timer_t, list);
        if (current_tick >= timer->timeout_tick) {
            /* timeout: invoke the callback and remove the timer */
            timer->callback_func(timer->parameter);
            node = node->next;
            list_del(node->prev);
        } else {
            node = node->next;
        }
    }

    enable_preempt();
}

