uint16_t alloc_inode()
{
    uint16_t ret = 0xffff;
    read_inodemap();
    for(int i = 0; i < 512; i++){
        uint8_t byte = *(((uint8_t*)inodemap) + i);
        if(byte != 0xff){
            int bit = 0;
            while(byte & (0x01 << bit)){
                bit++;
            }
            ret = 8 * i + bit;
            byte = byte | (0x01 << bit);
            *(((uint8_t*)inodemap) + i) = byte;
            write_inodemap();
            read_superblock();
            superblock->used_inode_num = superblock->used_inode_num + 1;
            write_superblock();
            break;
        }
    }
    return ret;
}

// Returns block id
uint32_t alloc_block()
{
    uint32_t ret = 0xffffffff;
    read_blockmap();
    for(int i = 0; i < 64 * 512; i++){
        uint8_t byte = *(((uint8_t*)blockmap) + i);
        if(byte != 0xff){
            int bit = 0;
            while(byte & (0x01 << bit)){
                bit++;
            }
            ret = 8 * i + bit;
            byte = byte | (0x01 << bit);
            *(((uint8_t*)blockmap) + i) = byte;
            write_blockmap();
            read_superblock();
            superblock->used_block_num = superblock->used_block_num + 1;
            write_superblock();
            break;
        }
    }
    return ret;
}

