{
    read_inodemap();
    uint8_t byte = *(((uint8_t*)inodemap) + inode_id / 8);
    byte = byte & ~(0x01 << (inode_id % 8));
    *(((uint8_t*)inodemap) + inode_id / 8) = byte;
    write_inodemap();
    read_superblock();
    superblock->used_inode_num = superblock->used_inode_num - 1;
    write_superblock();
}

