pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode)
{
    disable_preempt();

    /* search for a free pcb */
    int i;
    for(i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == -1){
            break;
        }
    }
    if(i == NUM_MAX_TASK){
        enable_preempt();
        return -1;
    }

