                nextdir_block_id = nextdir_inode->direct_blocks[0];
                lastdir_inode = nextdir_inode_id;
                lastdir_block = nextdir_block_id;
                break;
            }
        }
        if(i == 128){
            disable_sum();
            return 0;
        }

        // Last?
        if(dirname[dirname_pos] == '\0' || 
           (dirname[dirname_pos + 1] == '\0' && dirname[dirname_pos] == '/')){
            lastdir_inode = nextdir_inode_id;
            lastdir_block = nextdir_block_id;
            break;
        }
        else{
            dirname_pos++;
            read_block(nextdir_block_id);
            cur_dir = cached_block_base;
        }
    }

    disable_sum();
    /* Search Dir End */

    current_dir_inode = lastdir_inode;
    current_dir_block = lastdir_block;

    return 1;
}

int do_link(char* filename, char* newfile, int mode)
{
    /* Search Parent Dir */
    enable_sum();

    int filename_pos = 0;
    dir_t* cur_dir;
    uint16_t lastdir_inode;
    uint32_t lastdir_block;

    // search from root dir / current dir?
    if(filename[filename_pos] == '/'){
        read_superblock();
        read_block(superblock->root_block_id);
        cur_dir = cached_block_base;
        lastdir_inode = superblock->root_inode_id;
        lastdir_block = superblock->root_block_id;
        filename_pos++;    
    }
    else{
        read_block(current_dir_block);
        cur_dir = cached_block_base;
        lastdir_inode = current_dir_inode;
        lastdir_block = current_dir_block;
    }

    char nextdirname[29];
    while(1){
        // Get name of next dir
        int nextdirname_pos = 0;
        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
            nextdirname[nextdirname_pos++] = filename[filename_pos++];
        }
        nextdirname[nextdirname_pos] = '\0';

        // Last?
        if(filename[filename_pos] == '\0'){
            break;
        }

        // Search
        int i = 0;
        uint16_t nextdir_inode_id;
        uint32_t nextdir_block_id;
        for(i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
                nextdir_inode_id = cur_dir->entry[i].inode;
                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
                nextdir_block_id = nextdir_inode->direct_blocks[0];
                lastdir_inode = nextdir_inode_id;
                lastdir_block = nextdir_block_id;
                break;
            }
        }
        if(i == 128){
            disable_sum();
            return 0;
        }

        filename_pos++;
        read_block(nextdir_block_id);
        cur_dir = cached_block_base;
    }

    disable_sum();
    /* Search Parent Dir End */

    uint16_t inode_id = 0;
    int type = EMPTY;

    read_block(lastdir_block);
    cur_dir = cached_block_base;
    for(int i = 0; i < 128; i++){
        if(cur_dir->entry[i].type != EMPTY && !strcmp(cur_dir->entry[i].name, nextdirname)){
            inode_id = cur_dir->entry[i].inode;
            type = cur_dir->entry[i].type;
            break;
        }
    }
    if(type == EMPTY){
        return 0;
    }

    enable_sum();
    if(mode == 0){
        // hard link: share the same inode
        if(type == DIR){
            disable_sum();
            return 0;
        }

        inode_t* inode = read_inode(inode_id);
        inode->link = inode->link + 1;
        write_inode(inode_id);

        read_block(current_dir_block);
        cur_dir = cached_block_base;
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
                disable_sum();
                return 0;
            }
        }
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == EMPTY){
                cur_dir->entry[i].type = FILE;
                strcpy(cur_dir->entry[i].name, newfile);
                cur_dir->entry[i].inode = inode_id;
                write_block(current_dir_block);
                disable_sum();
                return 1;
            }
        }
    }
    else if(mode == 1){
        // soft link: new inode, but shares the target's blocks
        read_block(current_dir_block);
        cur_dir = cached_block_base;
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
                disable_sum();
                return 0;
            }
        }
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == EMPTY){
                uint16_t new_inode_id = alloc_inode();
                cur_dir->entry[i].type = type;
                strcpy(cur_dir->entry[i].name, newfile);
                cur_dir->entry[i].inode = new_inode_id;
                write_block(current_dir_block);

                inode_t* inode = read_inode(inode_id);
                uint32_t direct[10];
                uint32_t indirect[2];
                uint64_t size;
                uint32_t link;
                for(int j = 0; j < 10; j++){
                    direct[j] = inode->direct_blocks[j];
                }
                indirect[0] = inode->indirect_blocks[0];
                indirect[1] = inode->indirect_blocks[1];
                size = inode->size;
                link = inode->link;

                inode = read_inode(new_inode_id);
                inode->mode = 1;
                inode->owner = current_running[cpu_id]->pid;
                inode->size = size;
                inode->link = link;
                for(int j = 0; j < 10; j++){
                    inode->direct_blocks[j] = direct[j];
                }
                inode->indirect_blocks[0] = indirect[0];
                inode->indirect_blocks[1] = indirect[1];
                write_inode(new_inode_id);

                disable_sum();
                return 1;
            }
        }
    }

    disable_sum();
    return 0;
}

args.new_string:
int do_kill(pid_t pid)
{
    disable_preempt();

    /* search the pcb */
    pcb_t *kill_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            kill_pcb = &pcb[i];
            break;
        }
    }
    if(kill_pcb == NULL){
        enable_preempt();
        return 0;
    }

    /* remove the task from its queue (ready / blocked / sleep);
     * a no-op if the task is running and thus not queued */
    list_del(&kill_pcb->list);

    /* release all the binsems held by this task */
    release_binsems(kill_pcb);

    /* release the user stack */
    freePage(kill_pcb->user_stack_base, 1);

    /* wake up all the tasks waiting for this task */
    while(!list_empty(&kill_pcb->wait_list)){
        do_unblock(kill_pcb->wait_list.next);
    }

    if(kill_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        kill_pcb->status = TASK_ZOMBIE;
    }
    else{
        kill_pcb->status = TASK_EXITED;
        list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
    }

    /* reschedule if the task killed itself */
    if(kill_pcb == current_running[cpu_id]){
        scheduler();
    }

    enable_preempt();
    return 1;
}

