    }

    disable_sum();
    /* Search Parent Dir End */

    /* Modify FD */
    read_block(lastdir_block);
    cur_dir = cached_block_base;
    int fd_id;
    for(fd_id = 0; fd_id < 10; fd_id++){
        if(fd_list[fd_id].access == O_EMPTY){
            break;
        }
    }
    if(fd_id == 10){
        return -1;
    }

    for(int i = 0; i < 128; i++){
        if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, nextdirname)){
