// walk pgdir (pa) for va, returns the kva of the leaf level PTE,
// or NULL if any intermediate level is missing
static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
{
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        return NULL;
    }
    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
        return NULL;
    }
    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
    return &last_level_pgdir[VPN0];
}

// same as walk_pgdir, but allocate the missing intermediate levels
static PTE* walk_pgdir_alloc(uintptr_t va, uintptr_t pgdir)
{
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(&pgdir_kva[VPN2], (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&pgdir_kva[VPN2], _PAGE_PRESENT);
    }
    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(&second_level_pgdir[VPN1], (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&second_level_pgdir[VPN1], _PAGE_PRESENT);
    }
    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
    return &last_level_pgdir[VPN0];
}

uintptr_t shm_page_get(int key)
{
    int i = key % SHM_PAGE_NUM;
    // shared pages are mapped in the share area, one page per key
    uintptr_t va = 0x1000lu + i * PAGE_SIZE;
    pcb_t *cur = current_running[cpu_id];

    if(shm_page[i].count == 0){
        // first process getting this page: allocate a pinned page and zero it
        uintptr_t pa = alloc_user_page(1, NULL);
        memset((void*)pa2kva(pa), 0, PAGE_SIZE);
        shm_page[i].pa = pa;
        shm_page[i].count = 1;
    }
    else{
        shm_page[i].count++;
    }

    // map the shared physical page into the current address space
    PTE *pte = walk_pgdir_alloc(va, (uintptr_t)cur->pgdir);
    set_pfn(pte, shm_page[i].pa >> NORMAL_PAGE_SHIFT);
    set_attribute(pte, _PAGE_PRESENT);
    set_attribute(pte, _PAGE_READ);
    set_attribute(pte, _PAGE_WRITE);
    set_attribute(pte, _PAGE_USER);
    set_attribute(pte, _PAGE_ACCESSED);
    set_attribute(pte, _PAGE_DIRTY);
    local_flush_tlb_all();

    return va;
}

void shm_page_dt(uintptr_t addr)
{
    pcb_t *cur = current_running[cpu_id];
    PTE *pte = walk_pgdir(addr, (uintptr_t)cur->pgdir);
    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        return;
    }

    uintptr_t pa = get_pa(*pte);
    for(int i = 0; i < SHM_PAGE_NUM; i++){
        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
            shm_page[i].count--;
            if(shm_page[i].count == 0){
                free_user_page(pa);
            }
            break;
        }
    }

    // unmap the page from the current address space
    *pte = 0;
    local_flush_tlb_all();
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    pcb_t *cur = current_running[cpu_id];
    uintptr_t va = stval;
    PTE *pte = walk_pgdir(va, (uintptr_t)cur->pgdir);

    if(pte != NULL && get_attribute(*pte, _PAGE_SOFT)){
        // the page was swapped out to sd: swap it back in
        int slot = get_pfn(*pte);
        ptr_t pa = alloc_user_page(0, pte);
        sbi_sd_read(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));
        disk_page[slot].valid = 0;

        clear_attribute(pte, _PAGE_SOFT);
        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(pte, _PAGE_PRESENT);
        set_attribute(pte, _PAGE_ACCESSED);
    }
    else if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        // the page has never been mapped: demand paging
        alloc_page_helper(va, (uintptr_t)cur->pgdir);
    }
    local_flush_tlb_all();
}

