args.new_string:
void scheduler(void)
{
    pcb_t *cur = current_running[cpu_id];

    // put the current task back into the ready queue if it is still runnable
    if(cur->status == TASK_RUNNING){
        cur->status = TASK_READY;
        cur->ready_tick = get_ticks();
        list_add_tail(&cur->list, &ready_queue);
    }

    // pick the highest-priority ready task allowed to run on this core
    list_node_t *next_node = max_priority_node();
    if(next_node == NULL){
        return;
    }
    list_del(next_node);
    pcb_t *next = list_entry(next_node, pcb_t, list);
    next->status = TASK_RUNNING;
    next->cpu_id = cpu_id;
    current_running[cpu_id] = next;
    current_cpu_running = next;

    // switch to its address space
    set_satp(SATP_MODE_SV39, 0, (uintptr_t)next->pgdir >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    disable_preempt();
    enable_sum();

    // 1. find a free pcb
    int i;
    for(i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == -1){
            break;
        }
    }
    if(i == NUM_MAX_TASK){
        disable_sum();
        enable_preempt();
        return 0;   // too many tasks
    }

    // 2. find the elf file
    unsigned char *binary;
    int length;
    if(!get_elf_file(file_name, &binary, &length)){
        disable_sum();
        enable_preempt();
        return -1;  // no such executable
    }

    // 3. initialize the pcb (same layout as init_pcb in main.c)
    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    pcb[i].user_sp = USER_STACK_ADDR;
    pcb[i].preempt_count = 0;
    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
    pcb[i].user_stack_base = pcb[i].user_sp;
    list_add_tail(&pcb[i].list, &ready_queue);
    init_list_head(&pcb[i].wait_list);
    pcb[i].binsem_num = 0;
    pcb[i].pid = process_id++;
    pcb[i].type = USER_PROCESS;
    pcb[i].status = TASK_READY;
    pcb[i].mode = mode;
    pcb[i].priority = 0;
    pcb[i].ready_tick = get_ticks();
    pcb[i].mask = current_running[cpu_id]->mask;
    pcb[i].pgdir = init_page_table();

    // 4. load the elf into the fresh address space
    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir, alloc_page_helper);
    if(entry == 0){
        // invalid elf: roll everything back
        list_del(&pcb[i].list);
        free_process_user_page(pcb[i].pgdir);
        free_user_page(kva2pa(pcb[i].kernel_stack_base - PAGE_SIZE));
        pcb[i].pid = -1;
        disable_sum();
        enable_preempt();
        return -2;
    }

    // 5. push the argv strings and the argv pointer array onto the new
    //    user stack (through the kernel mapping of its stack page)
    uintptr_t stack_kva = get_kva_of(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pcb[i].pgdir) + PAGE_SIZE;
    uintptr_t stack_va = USER_STACK_ADDR;
    if(argc < 0){
        argc = 0;
    }
    uintptr_t arg_va[argc ? argc : 1];
    for(int j = argc - 1; j >= 0; j--){
        int len = strlen(argv[j]) + 1;
        stack_kva -= len;
        stack_va -= len;
