void scheduler(void)
{
    pcb_t *prev_running = current_running[cpu_id];

    /* put the current process back into the ready queue if it is
     * still runnable; the kernel idle processes (pid 0) are never queued */
    if(prev_running->status == TASK_RUNNING && prev_running->pid != 0){
        prev_running->status = TASK_READY;
        prev_running->ready_tick = get_ticks();
        list_add_tail(&prev_running->list, &ready_queue);
    }

    /* pick the highest priority process that may run on this core */
    list_node_t *next_node = max_priority_node();
    pcb_t *next_running;
    if(next_node == NULL){
        next_running = (pcb_t*)(cpu_id == 0 ? core0_tp : core1_tp);
    }
    else{
        list_del(next_node);
        next_running = list_entry(next_node, pcb_t, list);
    }

    next_running->status = TASK_RUNNING;
    next_running->cpu_id = cpu_id;
    current_running[cpu_id] = next_running;
    current_cpu_running = next_running;

    /* switch the address space (pgdir is pa) */
    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next_running->pgdir) >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    // file_name and argv live in the caller's address space
    enable_sum();

    /* look up the elf file embedded in the kernel image */
    unsigned char *binary;
    int length;
    if(get_elf_file(file_name, &binary, &length) == 0){
        disable_sum();
        return -1;
    }

    /* find a free pcb */
    int i;
    for(i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == -1){
            break;
        }
    }
    if(i == NUM_MAX_TASK){
        disable_sum();
        return 0;
    }

    /* initialize the pcb */
    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    pcb[i].user_sp = USER_STACK_ADDR;
    pcb[i].preempt_count = 0;
    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
    pcb[i].user_stack_base = pcb[i].user_sp;
    init_list_head(&pcb[i].wait_list);
    pcb[i].binsem_num = 0;
    pcb[i].pid = process_id++;
    pcb[i].type = USER_PROCESS;
    pcb[i].status = TASK_READY;
    pcb[i].mode = mode;
    pcb[i].priority = 0;
    pcb[i].ready_tick = get_ticks();
    pcb[i].mask = 3;
    pcb[i].cursor_x = 0;
    pcb[i].cursor_y = 0;
    pcb[i].pgdir = init_page_table();

    /* load the elf into the fresh address space */
    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir, alloc_page_helper);

    /* copy argc/argv onto the new user stack */
    int total_len = 0;
    for(int j = 0; j < argc; j++){
        total_len += strlen(argv[j]) + 1;
    }
    uintptr_t argv_base = ROUNDDOWN(USER_STACK_ADDR - total_len, sizeof(uintptr_t)) - argc * sizeof(uintptr_t);
    uintptr_t str_sp = USER_STACK_ADDR;
    for(int j = 0; j < argc; j++){
        str_sp -= strlen(argv[j]) + 1;
        strcpy((char*)get_kva_of(str_sp, (uintptr_t)pcb[i].pgdir), argv[j]);
        *(uintptr_t*)get_kva_of(argv_base + j * sizeof(uintptr_t), (uintptr_t)pcb[i].pgdir) = str_sp;
    }
    pcb[i].user_sp = ROUNDDOWN(argv_base, 16);

    /* initialize the trap frame so the first schedule enters at the elf entry */
    regs_context_t *pt_regs = (regs_context_t *)(pcb[i].kernel_sp - sizeof(regs_context_t));
    pcb[i].kernel_sp -= sizeof(regs_context_t);
    pt_regs->regs[1] = (reg_t)entry;                // ra
    pt_regs->regs[2] = (reg_t)pcb[i].user_sp;       // sp
    pt_regs->regs[3] = (reg_t)__global_pointer$;    // gp
    pt_regs->regs[10] = (reg_t)argc;                // a0
    pt_regs->regs[11] = (reg_t)argv_base;           // a1
    pt_regs->sstatus = (reg_t)SR_SPIE;              // SPP = 0, SPIE = 1
    pt_regs->sepc = (reg_t)entry;                   // sepc
    pt_regs->sscratch = (reg_t)&pcb[i];             // sscratch = tp

    list_add_tail(&pcb[i].list, &ready_queue);

    disable_sum();
    return pcb[i].pid;
}

// release all the binary semaphores held by p, waking up blocked processes
static void release_all_binsem(pcb_t *p)
{
    while(p->binsem_num > 0){
        int binsem_id = p->binsem_id[p->binsem_num - 1];
        binsem_node_t *node = &binsem_nodes[binsem_id];
        node->sem++;
        p->binsem_num--;
        if(node->sem <= 0){
            // hand the semaphore over to the first blocked process
            list_node_t *unblocked_node = node->block_queue.next;
            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
            unblocked_pcb->binsem_num++;
            do_unblock(unblocked_node);
        }
    }
}

void do_exit()
{
    pcb_t *exit_pcb = current_running[cpu_id];

    // release all the binary semaphores this process holds
    release_all_binsem(exit_pcb);

    // wake up the processes waiting for this process
    while(!list_empty(&exit_pcb->wait_list)){
        do_unblock(exit_pcb->wait_list.next);
    }

    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        // become a zombie until someone waits for us;
        // the vm resources are released later by do_waitpid
        exit_pcb->status = TASK_ZOMBIE;
    }
    else{
        // AUTO_CLEANUP_ON_EXIT: release the vm resources now and
        // let the kernel idle loop recycle the pcb and kernel stack
        free_process_user_page(exit_pcb->pgdir);
        free_pgdir_page((uintptr_t)exit_pcb->pgdir);
        exit_pcb->pgdir = NULL;
        exit_pcb->status = TASK_ZOMBIE;
        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
    }

    scheduler();
}

