152	/*
153	 * Virtual Memory Layout
154	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
155	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
156	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
157	 */
158	PTE* init_page_table()
159	{
160	    // allocate a fresh top level page table, returns pa
161	    PTE *pgdir = alloc_pgdir_page();
162	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
163	    PTE *boot_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
164	
165	    /*
166	     * share the kernel mappings with the boot page table:
167	     * entry 0x001: identity map of 0x5000_0000 ~ 0x6000_0000 (large pages)
168	     * entry 0x101: kernel virtual map (large pages)
169	     * both point to the shared second level table at PGDIR_PA + PAGE_SIZE,
170	     * so trap handling and kernel code stay reachable under every satp
171	     */
172	    pgdir_kva[0x001] = boot_pgdir_kva[0x001];
173	    pgdir_kva[0x101] = boot_pgdir_kva[0x101];
174	
175	    // map one page for the user stack: [USER_STACK_ADDR - PAGE_SIZE, USER_STACK_ADDR)
176	    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
177	
178	    return pgdir;
179	}

