151	#define USER_CODE_BEGIN 0x10000lu
152	#define USER_CODE_END   0x13000lu
153	#define SHM_BASE        0x1000lu
154	
155	/*
156	 * walk the 3-level sv39 page table (pgdir is pa) for `va`;
157	 * when `alloc` is non-zero, missing intermediate levels are
158	 * allocated from the pgdir page pool.
159	 * returns the kva of the leaf pte, or NULL if not present.
160	 */
161	static PTE *get_leaf_pte(uintptr_t va, PTE *pgdir, int alloc)
162	{
163	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
164	    uint64_t vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
165	    uint64_t vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
166	    uint64_t vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;
167	
168	    if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
169	        if(!alloc){
170	            return NULL;
171	        }
172	        PTE *new_pgdir = alloc_pgdir_page();
173	        set_pfn(&pgdir_kva[vpn2], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
174	        set_attribute(&pgdir_kva[vpn2], _PAGE_PRESENT);
175	    }
176	    PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
177	
178	    if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
179	        if(!alloc){
180	            return NULL;
181	        }
182	        PTE *new_pgdir = alloc_pgdir_page();
183	        set_pfn(&second_kva[vpn1], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
184	        set_attribute(&second_kva[vpn1], _PAGE_PRESENT);
185	    }
186	    PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[vpn1]));
187	
188	    return &last_kva[vpn0];
189	}
190	
191	/*
192	 * Virtual Memory Layout
193	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
194	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
195	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
196	 */
197	PTE* init_page_table()
198	{
199	    PTE *pgdir = alloc_pgdir_page();
200	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
201	
202	    /* share the kernel mapping (kva area) with the kernel page table,
203	     * so that the kernel is mapped in every process's address space */
204	    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
205	    pgdir_kva[0x101] = kernel_pgdir[0x101];
206	
207	    /* pre-allocate and map the user code region, so that load_elf()
208	     * can copy the segments through get_kva_of() */
209	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
210	        PTE *leaf = get_leaf_pte(va, pgdir, 1);
211	        ptr_t pa = alloc_user_page(0, leaf);
212	        clear_pgdir((PTE *)pa2kva(pa));
213	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
214	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
215	                            _PAGE_EXEC | _PAGE_USER |
216	                            _PAGE_ACCESSED | _PAGE_DIRTY);
217	    }
218	
219	    return pgdir;
220	}
221	
222	void free_process_user_page(PTE* pgdir)
223	{
224	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
225	    for(int i = 0; i < NUM_PTE_ENTRY; i++){
226	        if(!get_attribute(pgdir_kva[i], _PAGE_PRESENT)){
227	            continue;
228	        }
229	        if(i == 0x101){
230	            /* the kernel mapping is shared, do not free it */
231	            continue;
232	        }
233	        PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[i]));
234	        for(int j = 0; j < NUM_PTE_ENTRY; j++){
235	            if(!get_attribute(second_kva[j], _PAGE_PRESENT)){
236	                continue;
237	            }
238	            PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[j]));
239	            for(int k = 0; k < NUM_PTE_ENTRY; k++){
240	                uintptr_t va = ((uintptr_t)i << VPN2_SHIFT) |
241	                               ((uintptr_t)j << VPN1_SHIFT) |
242	                               ((uintptr_t)k << VPN0_SHIFT);
243	                if(get_attribute(last_kva[k], _PAGE_SOFT)){
244	                    /* the page is in the swap area, free the disk slot */
245	                    disk_page[get_pfn(last_kva[k])].valid = 0;
246	                    continue;
247	                }
248	                if(!get_attribute(last_kva[k], _PAGE_PRESENT)){
249	                    continue;
250	                }
251	                uintptr_t pa = get_pa(last_kva[k]);
252	                if(va >= SHM_BASE && va < USER_CODE_BEGIN){
253	                    /* shared page: only freed when the last user detaches */
254	                    int key = (va - SHM_BASE) / PAGE_SIZE;
255	                    shm_page[key].count--;
256	                    if(shm_page[key].count == 0){
257	                        free_user_page(pa);
258	                        shm_page[key].pa = 0;
259	                    }
260	                }
261	                else{
262	                    free_user_page(pa);
263	                }
264	            }
265	            free_pgdir_page(kva2pa((uintptr_t)last_kva));
266	        }
267	        free_pgdir_page(kva2pa((uintptr_t)second_kva));
268	    }
269	    free_pgdir_page((uintptr_t)pgdir);
270	}
271	
272	uintptr_t shm_page_get(int key)
273	{
274	    if(key < 0 || key >= SHM_PAGE_NUM){
275	        return 0;
276	    }
277	    uintptr_t va = SHM_BASE + key * PAGE_SIZE;
278	    PTE *pgdir = current_running[cpu_id]->pgdir;
279	    PTE *leaf = get_leaf_pte(va, pgdir, 1);
280	
281	    if(shm_page[key].count == 0){
282	        /* first user: allocate the physical shared page */
283	        uintptr_t pa = alloc_user_page(1, NULL);
284	        clear_pgdir((PTE *)pa2kva(pa));
285	        shm_page[key].pa = pa;
286	    }
287	    shm_page[key].count++;
288	
289	    set_pfn(leaf, shm_page[key].pa >> NORMAL_PAGE_SHIFT);
290	    set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
291	                        _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
292	    local_flush_tlb_all();
293	    return va;
294	}
295	
296	void shm_page_dt(uintptr_t addr)
297	{
298	    int key = (addr - SHM_BASE) / PAGE_SIZE;
299	    if(key < 0 || key >= SHM_PAGE_NUM){
300	        return;
301	    }
302	    PTE *pgdir = current_running[cpu_id]->pgdir;
303	    PTE *leaf = get_leaf_pte(addr, pgdir, 0);
304	    if(leaf != NULL){
305	        *leaf = 0;
306	    }
307	    local_flush_tlb_all();
308	
309	    shm_page[key].count--;
310	    if(shm_page[key].count <= 0){
311	        shm_page[key].count = 0;
312	        free_user_page(shm_page[key].pa);
313	        shm_page[key].pa = 0;
314	    }
315	}
316	
317	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
318	{
319	    /* kernel must not page fault */
320	    if(stval >= KERNEL_MEM_OFFSET){
321	        handle_other(regs, stval, cause);
322	        return;
323	    }
324	
325	    uintptr_t va = stval & VA_MASK;
326	    PTE *pgdir = current_running[cpu_id]->pgdir;
327	    PTE *leaf = get_leaf_pte(va, pgdir, 1);
328	
329	    if(get_attribute(*leaf, _PAGE_SOFT)){
330	        /* the page was swapped out: swap it back in */
331	        int slot = get_pfn(*leaf);
332	        ptr_t pa = alloc_user_page(0, leaf);
333	        sbi_sd_read((unsigned int)pa, PAGE_SIZE / 512,
334	                    SWAP_BEGIN + slot * (PAGE_SIZE / 512));
335	        disk_page[slot].valid = 0;
336	        clear_attribute(leaf, _PAGE_SOFT);
337	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
338	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
339	                            _PAGE_EXEC | _PAGE_USER |
340	                            _PAGE_ACCESSED | _PAGE_DIRTY);
341	    }
342	    else if(!get_attribute(*leaf, _PAGE_PRESENT)){
343	        /* demand paging: allocate a fresh, zeroed page */
344	        ptr_t pa = alloc_user_page(0, leaf);
345	        clear_pgdir((PTE *)pa2kva(pa));
346	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
347	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
348	                            _PAGE_EXEC | _PAGE_USER |
349	                            _PAGE_ACCESSED | _PAGE_DIRTY);
350	    }
351	
352	    local_flush_tlb_all();
353	    /* return without advancing sepc: re-execute the faulting instruction */
354	}

