26	long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
27	{
28	    // receive packet by calling network driver's function
29	    // wait until you receive enough packets(`num_packet`).
30	    if(num_packet > RXBD_CNT){
31	        return -1;
32	    }
33	    recv_transaction = 1;
34	    enable_sum();
35	    for(int i = 0; i < num_packet; i++){
36	        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
37	        rx_len[i] = 0;
38	    }
39	    EmacPsRecv(&EmacPsInstance, 0, num_packet);
40	
41	    if(net_poll_mode == 0){
42	        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);
43	        rx_curr = addr;
44	        rx_tail = 0;
45	        for(int i = 0; i < num_packet; i++){
46	            memcpy((uint8_t*)rx_curr, (uint8_t*)&rx_buffers[i], rx_len[i]);
47	            *(frLength + i) = rx_len[i];
48	            rx_curr += rx_len[i];
49	            rx_tail += rx_len[i];
50	        }
51	        disable_sum();
52	        recv_transaction = 0;
53	        return rx_tail;
54	    }
55	    else if(net_poll_mode == 1){
56	        _addr = addr;
57	        _num_packet = num_packet;
58	        _frLength = frLength;
59	        do_block(&current_running[cpu_id]->list, &net_recv_queue);
60	        scheduler();
61	        disable_sum();
62	        return 0;
63	    }
64	    else{
65	        return -1;
66	    }
67	}
68	
69	void do_net_send(uintptr_t addr, size_t length)
70	{
71	    // send all packet
72	    send_transaction = 1;
73	    enable_sum();
74	    memset(&tx_buffer, 0, sizeof(EthernetFrame));
75	    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, length);
76	    EmacPsSend(&EmacPsInstance, 0, length);
77	    if(net_poll_mode == 0){
78	        EmacPsWaitSend(&EmacPsInstance);
79	        send_transaction = 0;
80	    }
81	    else if(net_poll_mode == 1){
82	        do_block(&current_running[cpu_id]->list, &net_send_queue);
83	        scheduler();
84	    }
85	    disable_sum();
86	}
87	
88	void do_net_irq_mode(int mode)
89	{
90	    // turn on/off network driver's interrupt mode
91	    if(net_poll_mode != mode){
92	        assert(recv_transaction == 0);
93	        assert(send_transaction == 0);
94	        net_poll_mode = mode;
95	        if(net_poll_mode == 1){
96	            XEmacPs_IntEnable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
97	                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
98	            XEmacPs_WriteReg(EmacPsInstance.Config.BaseAddress, XEMACPS_IDR_OFFSET, 0);
99	        }
100	        else if(net_poll_mode == 0){
101	            XEmacPs_IntDisable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
102	                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
103	        }
104	    }
105	}

