26	/* current running task PCB */
27	pcb_t * volatile current_running;
28	
29	/* global process id */
30	pid_t process_id = 1;
31	
32	/* 
33	 * Only modify PCB, current_running, process_id and ready_queue
34	 * DO NOT STORE OR RESTORE 
35	 * trick: modify $tp in ret_from_exception to ensure
36	 * disable_preempt() and enable_preempt() modify the same PCB
37	 */
38	void scheduler(void)
39	{
40	    test_sched_time(BEGIN);
41	
42	    /* save the cursor of the current task */
43	    current_running->cursor_x = screen_cursor_x;
44	    current_running->cursor_y = screen_cursor_y;
45	
46	    /* if the current task is still running, put it back into the ready queue */
47	    if (current_running->status == TASK_RUNNING) {
48	        list_add_tail(&current_running->list, &ready_queue);
49	        current_running->status = TASK_READY;
50	        current_running->ready_tick = get_ticks();
51	    }
52	
53	    /* pick the ready task with the highest priority */
54	    current_running = list_entry(max_priority_node(), pcb_t, list);
55	    list_del(&current_running->list);
56	    current_running->status = TASK_RUNNING;
57	    process_id = current_running->pid;
58	
59	    /* restore the cursor of the new task */
60	    vt100_move_cursor(current_running->cursor_x, current_running->cursor_y);
61	    screen_cursor_x = current_running->cursor_x;
62	    screen_cursor_y = current_running->cursor_y;
63	
64	    test_sched_time(END);
65	}
