67	// sleep(seconds)
68	void do_sleep(uint32_t sleep_time)
69	{
70	    // 1. block the current_running
71	    // 2. create a timer which calls `do_unblock` when timeout
72	    // 3. reschedule because the current_running is blocked
73	    do_block(&current_running->list, &sleep_queue);
74	    list_node_t* parameter = &current_running->list;
75	    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
76	    scheduler();
77	}
78	
79	// block the pcb task into the block queue
80	void do_block(list_node_t *pcb_node, list_head *queue)
81	{
82	    list_del(pcb_node);
83	    list_add_tail(pcb_node, queue);
84	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
85	}
86	
87	// unblock the `pcb` from the block queue
88	void do_unblock(list_node_t *pcb_node)
89	{
90	    list_del(pcb_node);
91	    list_add_tail(pcb_node, &ready_queue);
92	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
93	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
94	}
95	
96	list_node_t* max_priority_node(void)
97	{
98	    uint64_t current_tick = get_ticks();
99	
100	    /*
101	     * The effective priority of a ready task is its static priority aged
102	     * by the number of timer intervals it has waited in the ready queue;
103	     * the lower the value, the higher the priority.
104	     */
105	    list_node_t *max_node = ready_queue.next;
106	    pcb_t *max_pcb = list_entry(max_node, pcb_t, list);
107	    int max_priority = (int)max_pcb->priority
108	        - (int)((current_tick - max_pcb->ready_tick) / timer_interval);
109	
110	    list_node_t *node;
111	    for (node = ready_queue.next->next; node != &ready_queue; node = node->next) {
112	        pcb_t *pcb = list_entry(node, pcb_t, list);
113	        int priority = (int)pcb->priority
114	            - (int)((current_tick - pcb->ready_tick) / timer_interval);
115	        if (priority < max_priority) {
116	            max_node = node;
117	            max_priority = priority;
118	        }
119	    }
120	
121	    return max_node;
122	}
