124	uint64_t sched_used_time;
125	void test_sched_time(int op)
126	{
127		int print_location = 13;
128		if(op == BEGIN){
129			sched_used_time = get_ticks();
130		}
131		else if(op == END){
132			sched_used_time = get_ticks() - sched_used_time;
133		    vt100_move_cursor(1, print_location);
134		    printk("time_base:\t\t%d", time_base);
135		    vt100_move_cursor(1, print_location + 1);
136		    printk("timer_interval:\t\t%d", timer_interval);
137		    vt100_move_cursor(1, print_location + 2);
138		    printk("sched_used_time:\t%d", sched_used_time);
139		}
140	}

