6	LIST_HEAD(timer_queue);
7	
8	uint64_t time_elapsed = 0;
9	uint32_t time_base = 0;
10	uint64_t timer_interval = 0;
11	
12	void timer_create(TimerCallback func, void* parameter, uint64_t tick)
13	{
14	    disable_preempt();
15	
16	    list_add_tail(&current_running->timer.list, &timer_queue);
17	    current_running->timer.timeout_tick = tick;
18	    current_running->timer.callback_func = func;
19	    current_running->timer.parameter = parameter;
20	
21	    enable_preempt();
22	}
23	
24	/* check all timers. if timeouts, call callback_func and free the timer */
25	void timer_check()
26	{
27	    disable_preempt();
28	
29	    uint64_t current_tick = get_ticks();
30	    list_node_t *node = timer_queue.next;
31	    while (node != &timer_queue) {
32	        timer_t *timer = list_entry(node, timer_t, list);
33	        if (current_tick >= timer->timeout_tick) {
34	            /* timeout: invoke the callback and remove the timer */
35	            timer->callback_func(timer->parameter);
36	            node = node->next;
37	            list_del(node->prev);
38	        } else {
39	            node = node->next;
40	        }
41	    }
42	
43	    enable_preempt();
44	}
45	
46	uint64_t get_ticks()
47	{
48	    __asm__ __volatile__(
49	        "rdtime %0"
50	        : "=r"(time_elapsed));
51	    return time_elapsed;
52	}
53	
54	uint64_t get_timer()
55	{
56	    return get_ticks() / time_base;
57	}
58	
59	uint64_t get_time_base()
60	{
61	    return time_base;
62	}
63	
64	void latency(uint64_t time)
65	{
66	    uint64_t begin_time = get_timer();
67	
68	    while (get_timer() - begin_time < time);
69	    return;
70	}

