5	
6	binsem_node_t binsem_nodes[BINSEM_NUMBER];
7	
8	// a simple hash function
9	static int binsem_hash(uint64_t x)
10	{
11	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
12	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
13	    x = x ^ (x >> 31);
14	    return x % BINSEM_NUMBER;
15	}
16	
17	void init_system_binsem()
18	{
19	    for(int i = 0; i < BINSEM_NUMBER; i++){
20	        binsem_nodes[i].sem = 1;
21	        init_list_head(&binsem_nodes[i].block_queue);
22	    }
23	}
24	
25	int binsem_get(int key)
26	{ 
27	    return binsem_hash((uint64_t)key);
28	}
29	
30	void binsem_op(int binsem_id, int op)
31	{
32	    disable_preempt();
33	
34	    binsem_node_t *node = &binsem_nodes[binsem_id];
35	    if (op == BINSEM_OP_LOCK) {
36	        node->sem--;
37	        if (node->sem < 0) {
38	            /* the semaphore is taken: block the current task */
39	            do_block(&current_running->list, &node->block_queue);
40	            scheduler();
41	        }
42	    } else if (op == BINSEM_OP_UNLOCK) {
43	        node->sem++;
44	        if (node->sem <= 0) {
45	            /* there are waiters: wake one of them up */
46	            do_unblock(node->block_queue.next);
47	            scheduler();
48	        }
49	    }
50	
51	    enable_preempt();
52	}

