5	void spin_lock_init(spin_lock_t *lock)
6	{
7	    atomic_swap_d(UNLOCKED, (ptr_t)(&lock->status));
8	}
9	void spin_lock_try_acquire(spin_lock_t *lock)
10	{
11	    while(lock->status == LOCKED){
12	        ;
13	    }
14	}
15	void spin_lock_acquire(spin_lock_t *lock)
16	{
17	    spin_lock_try_acquire(lock);
18	    atomic_swap_d(LOCKED, (ptr_t)(&lock->status));
19	}
20	void spin_lock_release(spin_lock_t *lock)
21	{
22	    atomic_swap_d(UNLOCKED, (ptr_t)(&lock->status));
23	}
24	
25	void do_mutex_lock_init(mutex_lock_t *lock)
26	{
27	    lock->lock.status = UNLOCKED;
28	    init_list_head(&lock->block_queue);
29	}
30	void do_mutex_lock_acquire(mutex_lock_t *lock)
31	{
32	    while (lock->lock.status == LOCKED) {
33	        /* the lock is held: block the current task on the lock's queue */
34	        do_block(&current_running->list, &lock->block_queue);
35	        do_scheduler();
36	    }
37	    lock->lock.status = LOCKED;
38	}
39	void do_mutex_lock_release(mutex_lock_t *lock)
40	{
41	    lock->lock.status = UNLOCKED;
42	    if (!list_empty(&lock->block_queue)) {
43	        /* wake up one blocked task and let it compete for the lock */
44	        do_unblock(lock->block_queue.next);
45	        do_scheduler();
46	    }
47	}

