17	// a simple hash function
18	static int futex_hash(uint64_t x)
19	{
20	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
21	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
22	    x = x ^ (x >> 31);
23	    return x % FUTEX_BUCKETS;
24	}
25	
26	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
27	{
28	    int bucket = futex_hash((uint64_t)val_addr);
29	    list_head *head = &futex_buckets[bucket];
30	
31	    /* search the bucket for a node matching this address */
32	    list_node_t *p;
33	    for (p = head->next; p != head; p = p->next) {
34	        futex_node_t *node = list_entry(p, futex_node_t, list);
35	        if (node->futex_key == (futex_key_t)val_addr) {
36	            return node;
37	        }
38	    }
39	
40	    if (create) {
41	        /* allocate and initialize a new node for this address */
42	        futex_node_t *node = (futex_node_t *)kmalloc(sizeof(futex_node_t));
43	        node->futex_key = (futex_key_t)val_addr;
44	        init_list_head(&node->block_queue);
45	        list_add_tail(&node->list, &futex_buckets[bucket]);
46	        return node;
47	    }
48	
49	    return NULL;
50	}
51	
52	void futex_wait(volatile uint64_t *val_addr, uint64_t val)
53	{
54	    disable_preempt();
55	
56	    futex_node_t *node = get_node(val_addr, 1);
57	    assert(node);
58	    if (*val_addr == val) {
59	        /* the value still matches: block until a futex_wakeup */
60	        do_block(&current_running->list, &node->block_queue);
61	        scheduler();
62	    }
63	
64	    enable_preempt();
65	}
66	
67	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
68	{
69	    disable_preempt();
70	
71	    futex_node_t *node = get_node(val_addr, 0);
72	    if (node != NULL) {
73	        for (int i = 0; i < num_wakeup; ++i) {
74	            if (list_empty(&node->block_queue)) {
75	                break;
76	            }
77	            do_unblock(node->block_queue.next);
78	        }
79	    }
80	    scheduler();
81	
82	    enable_preempt();
83	}

