18	pcb_t pcb[NUM_MAX_TASK];
19	pcb_t kernel_pcb[NR_CPUS];
20	const pcb_t *core0_tp = &kernel_pcb[0];
21	const pcb_t *core1_tp = &kernel_pcb[1];
