202	/* release all the binsem locks acquired by `p` */
203	static void release_binsem(pcb_t *p)
204	{
205	    for(int i = 0; i < p->binsem_num; i++){
206	        int binsem_id = p->binsem_id[i];
207	        binsem_nodes[binsem_id].sem++;
208	        if(binsem_nodes[binsem_id].sem <= 0){
209	            list_node_t *unblocked_node = binsem_nodes[binsem_id].block_queue.next;
210	            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
211	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
212	            unblocked_pcb->binsem_num++;
213	            do_unblock(unblocked_node);
214	        }
215	    }
216	    p->binsem_num = 0;
217	}
218	
219	void do_exit()
220	{
221	    pcb_t *exit_pcb = current_running[cpu_id];
222	
223	    /* release the acquired binsem locks */
224	    release_binsem(exit_pcb);
225	
226	    /* release the address space: user pages, swap slots and page table */
227	    free_process_user_page(exit_pcb->pgdir);
228	
229	    /* wake up the processes waiting for this one */
230	    while(!list_empty(&exit_pcb->wait_list)){
231	        do_unblock(exit_pcb->wait_list.next);
232	    }
233	
234	    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
235	        /* keep the pcb so that do_waitpid() can find and reap it */
236	        exit_pcb->status = TASK_ZOMBIE;
237	    }
238	    else{
239	        /* hand over to the reaper in main(): it releases the pcb
240	         * and the kernel stack (we are still running on it) */
241	        exit_pcb->status = TASK_EXITED;
242	        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
243	    }
244	
245	    scheduler();
246	}
247	
248	// sleep(seconds)
249	void do_sleep(uint32_t sleep_time)
250	{
251	    // 1. block the current_running
252	    // 2. create a timer which calls `do_unblock` when timeout
253	    // 3. reschedule because the current_running is blocked
254	    do_block(&current_running[cpu_id]->list, &sleep_queue);
255	    list_node_t* parameter = &current_running[cpu_id]->list;
256	    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
257	    scheduler();
258	}
