260	int do_kill(pid_t pid)
261	{
262	    /* kernel processes and the shell cannot be killed */
263	    if(pid <= 1){
264	        return 0;
265	    }
266	
267	    /* search the pcb */
268	    pcb_t *kill_pcb = NULL;
269	    for(int i = 0; i < NUM_MAX_TASK; i++){
270	        if(pcb[i].pid == pid){
271	            kill_pcb = &pcb[i];
272	            break;
273	        }
274	    }
275	    if(kill_pcb == NULL){
276	        return 0;
277	    }
278	
279	    /* killing itself is just exiting */
280	    if(kill_pcb == current_running[cpu_id]){
281	        do_exit();
282	        return 1;
283	    }
284	
285	    /* remove it from the queue(ready/blocked/sleep) it is in */
286	    list_del(&kill_pcb->list);
287	
288	    /* release the acquired binsem locks */
289	    release_binsem(kill_pcb);
290	
291	    /* release the address space: user pages, swap slots and page table */
292	    free_process_user_page(kill_pcb->pgdir);
293	
294	    /* wake up the processes waiting for this one */
295	    while(!list_empty(&kill_pcb->wait_list)){
296	        do_unblock(kill_pcb->wait_list.next);
297	    }
298	
299	    /* it is not running on this core, so release the kernel
300	     * stack and the pcb directly */
301	    free_user_page(kva2pa(kill_pcb->kernel_stack_base - PAGE_SIZE));
302	    kill_pcb->status = TASK_EXITED;
303	    kill_pcb->pid = -1;
304	    return 1;
305	}
306	
307	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
308	{
309	    while(1){
310	        /* search the pcb */
311	        pcb_t *wait_pcb = NULL;
312	        for(int i = 0; i < NUM_MAX_TASK; i++){
313	            if(pcb[i].pid == pid){
314	                wait_pcb = &pcb[i];
315	                break;
316	            }
317	        }
318	        if(wait_pcb == NULL){
319	            return -1;
320	        }
321	
322	        if(wait_pcb->status == TASK_ZOMBIE){
323	            /* reap the zombie: release its kernel stack and pcb */
324	            free_user_page(kva2pa(wait_pcb->kernel_stack_base - PAGE_SIZE));
325	            wait_pcb->status = TASK_EXITED;
326	            wait_pcb->pid = -1;
327	            return pid;
328	        }
329	        if(wait_pcb->status == TASK_EXITED){
330	            return pid;
331	        }
332	
333	        /* block until the target process exits */
334	        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
335	        scheduler();
336	    }
337	}
