8	ptr_t allocPage(int numPage)
9	{
10	    ptr_t ret;
11	    if(numPage == 1 && free_page_num){
12	        ret = free_page[--free_page_num];
13	    }
14	    else{
15	        // align PAGE_SIZE
16	        ret = ROUND(memCurr, PAGE_SIZE) + numPage * PAGE_SIZE;
17	        memCurr = ret;
18	    }
19	    return ret;
