46	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point, pcb_t *pcb)
47	{
48	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
49	    pcb->kernel_sp -= sizeof(regs_context_t);
50	
51	    /* initialization registers: ra, sp, gp, sepc, sstatus, sepc, sscratch */
52	    pt_regs->regs[1] = (reg_t)entry_point;      //ra
53	    pt_regs->regs[2] = (reg_t)user_stack;       //sp
54	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
55	    pt_regs->sstatus = (reg_t)SR_SPIE;          //SPP = 0, SPIE = 1
56	    pt_regs->sepc = (reg_t)entry_point;         //sepc
57	    pt_regs->sscratch = (reg_t)pcb;             //sscratch = tp
58	}
