55	        if(user_page[i].valid == 0){
56	            break;
57	        }
58	    }
59	    if(i == USER_PAGE_NUM){
60	        // no free user page: swap a victim out to the disk
61	        ptr_t victim = selete_page();
62	        write_to_sd(victim);
63	        i = pa2num(victim);
