243	// pgdir is pa. if va is not mapped, then mapped it
244	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
245	{
246	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
247	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
248	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
249	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
250	
251	    // build the intermediate levels on demand
252	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
253	        PTE *second_level_pgdir = alloc_pgdir_page();
254	        set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
255	        set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
256	    }
257	    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
258	    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
259	        PTE *last_level_pgdir = alloc_pgdir_page();
260	        set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
261	        set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
262	    }
263	    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
264	
265	    // map a freshly allocated user page if the leaf is not present
266	    if(!get_attribute(last_level_kva[VPN0], _PAGE_PRESENT)){
267	        ptr_t pa = alloc_user_page(0, last_level_kva + VPN0);
268	        set_pfn(last_level_kva + VPN0, pa >> NORMAL_PAGE_SHIFT);
269	        set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
270	        set_attribute(last_level_kva + VPN0, _PAGE_READ);
271	        set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
272	        set_attribute(last_level_kva + VPN0, _PAGE_EXEC);
273	        set_attribute(last_level_kva + VPN0, _PAGE_USER);
274	        set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
275	        set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);
276	    }
277	    return get_kva_of(va, pgdir);
278	}
279	
280	// shared-memory pages live at 0x0_0000_1000 ~ 0x0_0001_0000
281	#define SHM_BASE 0x1000lu
282	
283	uintptr_t shm_page_get(int key)
284	{
285	    disable_preempt();
286	    int i = key % SHM_PAGE_NUM;
287	    // first user of this key: allocate the physical shared page
288	    if(shm_page[i].count == 0){
289	        shm_page[i].pa = alloc_user_page(1, NULL);
290	        memset((void*)pa2kva(shm_page[i].pa), 0, PAGE_SIZE);
291	    }
292	    shm_page[i].count++;
293	
294	    // map the shared page into the current process's address space
295	    uintptr_t va = SHM_BASE + i * PAGE_SIZE;
296	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
297	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
298	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
299	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
300	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
301	
302	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
303	        PTE *second_level_pgdir = alloc_pgdir_page();
304	        set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
305	        set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
306	    }
307	    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
308	    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
309	        PTE *last_level_pgdir = alloc_pgdir_page();
310	        set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
311	        set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
312	    }
313	    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
314	    set_pfn(last_level_kva + VPN0, shm_page[i].pa >> NORMAL_PAGE_SHIFT);
315	    set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
316	    set_attribute(last_level_kva + VPN0, _PAGE_READ);
317	    set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
318	    set_attribute(last_level_kva + VPN0, _PAGE_USER);
319	    set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
320	    set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);
321	
322	    local_flush_tlb_all();
323	    enable_preempt();
324	    return va;
325	}
326	
327	void shm_page_dt(uintptr_t addr)
328	{
329	    disable_preempt();
330	    int i = (addr - SHM_BASE) / PAGE_SIZE;
331	
332	    // unmap the page from the current process's address space
333	    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);
334	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
335	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
336	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
337	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
338	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
339	    if(get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
340	        PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
341	        if(get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
342	            PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
343	            last_level_kva[VPN0] = 0;
344	        }
345	    }
346	
347	    if(i >= 0 && i < SHM_PAGE_NUM && shm_page[i].count > 0){
348	        shm_page[i].count--;
349	        // last user of this shared page: release the physical page
350	        if(shm_page[i].count == 0){
351	            free_user_page(shm_page[i].pa);
352	            shm_page[i].pa = 0;
353	        }
354	    }
355	    local_flush_tlb_all();
356	    enable_preempt();
357	}
